async function r(t){try{const e=await fetch("/api/send-enquiry",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(t)});let s={};try{s=await e.json()}catch{}return e.ok?{success:!0,message:s.message||"Your enquiry has been submitted successfully! We will contact you shortly.",adminSent:s.adminSent,customerSent:s.customerSent}:{success:!1,message:s.message||`Failed to submit enquiry (Error ${e.status}). Please try calling us directly.`}}catch(e){return console.error("[submitEnquiry Error]:",e),{success:!1,message:"Unable to reach the server. Please check your internet connection or call our office directly."}}}export{r as s};
